import { proxyActivities, workflowInfo } from "@temporalio/workflow";

type Order = { id: string; customerId: string; totalCents: number };
type OrderActivities = {
  reserveInventory(input: { orderId: string }): Promise<{ reservationId: string }>;
  capturePayment(input: { orderId: string; idempotencyKey: string; amountCents: number }): Promise<void>;
  markFulfilled(input: { orderId: string; reservationId: string }): Promise<void>;
};
const activities = proxyActivities<OrderActivities>({
  startToCloseTimeout: "2 minutes",
  retry: { initialInterval: "1 second", maximumAttempts: 5 },
});

export async function processOrder(order: Order): Promise<{ reservationId: string }> {
  const reservation = await activities.reserveInventory({ orderId: order.id });
  await activities.capturePayment({
    orderId: order.id,
    idempotencyKey: workflowInfo().workflowId,
    amountCents: order.totalCents,
  });
  await activities.markFulfilled({ orderId: order.id, reservationId: reservation.reservationId });
  return reservation;
}

