import { Inngest } from "inngest";
import { capturePayment, markFulfilled, reserveInventory } from "./order-activities";

type OrderCreated = { id: string; customerId: string; totalCents: number };
export const inngest = new Inngest({ id: "storefront" });

function parseOrderCreated(value: unknown): OrderCreated {
  if (!value || typeof value !== "object") throw new TypeError("Invalid order event");
  const record = value as Record<string, unknown>;
  if (
    typeof record.id !== "string" ||
    typeof record.customerId !== "string" ||
    typeof record.totalCents !== "number" ||
    !Number.isSafeInteger(record.totalCents) ||
    record.totalCents < 0
  ) {
    throw new TypeError("Invalid order event");
  }
  return { id: record.id, customerId: record.customerId, totalCents: record.totalCents };
}

export const processOrder = inngest.createFunction(
  { id: "process-order", retries: 5 },
  { event: "orders/created" },
  async ({ event, step }) => {
    const order = parseOrderCreated(event.data);
    const reservation = await step.run("reserve-inventory", () =>
      reserveInventory({ orderId: order.id }),
    );
    await step.run("capture-payment", () =>
      capturePayment({
        orderId: order.id,
        idempotencyKey: event.id,
        amountCents: order.totalCents,
      }),
    );
    await step.run("mark-fulfilled", () =>
      markFulfilled({ orderId: order.id, reservationId: reservation.reservationId }),
    );
    return { orderId: order.id, reservationId: reservation.reservationId };
  },
);
